import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

export type MigrateOptions = {
  cwd?: string
  write?: boolean
}

type Finding = {
  id: string
  severity: 'replace' | 'optional' | 'info'
  pattern: string
  advice: string
}

const FINDINGS: Array<{
  id: string
  severity: Finding['severity']
  patterns: string[]
  advice: string
}> = [
  {
    id: 'preview-window-machine',
    severity: 'replace',
    patterns: ['preview-window-machine', 'previewWindowMachine'],
    advice: 'Replace with RangeSlider from @aeon-ui/react or @aeon-ui/ui (rangeSliderMachine).',
  },
  {
    id: 'file-dropzone',
    severity: 'replace',
    patterns: ['file-dropzone-machine', 'fileDropzoneMachine', 'FileDropzone'],
    advice: 'Replace with FileUpload compound (fileUploadMachine) — idle | dragging | rejected.',
  },
  {
    id: 'sonner-bridge',
    severity: 'replace',
    patterns: ["from 'sonner'", 'from "sonner"', 'components/ui/sonner'],
    advice: 'Use Toast.Provider + useToast().publish / dismiss (aeon-ui-engine ≥ 1.2).',
  },
  {
    id: 'manual-link-button',
    severity: 'optional',
    patterns: ['data-aeon-scope="button"', 'buttonVariants('],
    advice:
      'Prefer <Button.Root asChild><Link … /></Button.Root> instead of hand-rolled data-aeon-* on anchors.',
  },
  {
    id: 'chakra',
    severity: 'info',
    patterns: ['@chakra-ui/react', '@ark-ui/react'],
    advice:
      'Migrate leaf → forms → overlays per docs/MIGRATION_FROM_ARK.md; see docs/MIGRATION.md for greenfield checklist.',
  },
  {
    id: 'alert-dialog-local',
    severity: 'optional',
    patterns: ['alertDialogMachine', 'role="alertdialog"'],
    advice:
      'Prefer Dialog/Prompt with dismissible=false for destructive confirms until AlertDialog ships.',
  },
]

const CANDIDATES = [
  'package.json',
  'package-lock.json',
  'pnpm-lock.yaml',
  'lib/preview-window-machine.ts',
  'lib/file-dropzone-machine.ts',
  'components/file-dropzone.tsx',
  'components/ui/sonner.tsx',
  'components/ui/alert-dialog.tsx',
  'components/ui/slider.tsx',
  'components/ui/button.tsx',
  'components/dual-login-buttons.tsx',
]

function walkHints(cwd: string): Finding[] {
  const hits: Finding[] = []
  let corpus = ''

  for (const rel of CANDIDATES) {
    const abs = join(cwd, rel)
    if (!existsSync(abs)) continue
    try {
      corpus += `\n${rel}\n${readFileSync(abs, 'utf8')}`
    } catch {
      /* ignore unreadable */
    }
  }

  for (const rule of FINDINGS) {
    const matched = rule.patterns.find((p) => corpus.includes(p))
    if (matched) {
      hits.push({
        id: rule.id,
        severity: rule.severity,
        pattern: matched,
        advice: rule.advice,
      })
    }
  }

  return hits
}

const CHECKLIST = `# Aeon migration checklist

Generated by \`npx aeon-ui migrate\`.

## Install

\`\`\`bash
npm install aeon-ui-engine@^1.4.0 react react-dom xstate @xstate/react
\`\`\`

\`\`\`ts
import 'aeon-ui-engine/aeon.css'
\`\`\`

## Agent setup

\`\`\`bash
npx aeon-ui init
\`\`\`

Paste \`aeon.cursorrules.md\` into Cursor rules. Keep domain machines in the app; use Aeon for chrome + interactive primitives.

## Statechart-first rule

1. Model interaction with an XState machine (or reuse Aeon machines).
2. Project \`snapshot\` → \`data-aeon-state\` / compound parts.
3. Do not invent parallel booleans for chart-owned concerns.

## New primitives (1.4+)

| Need | Use |
|------|-----|
| Two-thumb range | \`RangeSlider\` + \`rangeSliderMachine\` |
| Link styled as button | \`<Button.Root asChild><Link/></Button.Root>\` |
| Drag-drop file surface | \`FileUpload\` + \`fileUploadMachine\` |
| Toast | \`Toast.Provider\` + \`useToast()\` |
| Confirm sheet | \`Prompt\` / \`Dialog\` |

## Docs

- docs/MIGRATION.md (in aeon-ui-engine / AeonUI repo)
- docs/MIGRATION_FROM_ARK.md
- AGENTS.md
`

export function migrateAeon(options: MigrateOptions = {}) {
  const cwd = options.cwd ?? process.cwd()
  const write = options.write ?? true
  const findings = walkHints(cwd)
  const written: string[] = []

  if (write) {
    const path = join(cwd, 'AEON_MIGRATION_CHECKLIST.md')
    const findingsBlock =
      findings.length === 0
        ? '\n## Scan results\n\nNo known local workarounds detected in the quick scan.\n'
        : `\n## Scan results\n\n${findings
            .map((f) => `- **${f.severity}** \`${f.id}\` (matched \`${f.pattern}\`): ${f.advice}`)
            .join('\n')}\n`
    writeFileSync(path, `${CHECKLIST.trim()}\n${findingsBlock}`)
    written.push('write AEON_MIGRATION_CHECKLIST.md')
  }

  return { cwd, written, findings }
}
